using System.Collections.ObjectModel;
using System.IO;
using System.Net.Http;
using System.Text;
using System.Text.Json;
using System.Text.RegularExpressions;
using System.Windows;
using System.Windows.Input;
using System.Windows.Media;
using System.Windows.Threading;
using System.Xml.Linq;
namespace SonicForge.App;
public sealed record RadioStation(string Name,string Url);
public sealed record PodcastEpisode(string Title,string Url,string Date);
public sealed record GermanStation(string Name,string Url,string State,string Tags,string Codec);
public partial class RadioPodcastWindow : Window
{
 readonly ObservableCollection<RadioStation> stations=new(); readonly ObservableCollection<PodcastEpisode> episodes=new(); readonly ObservableCollection<GermanStation> searchResults=new(); readonly MediaPlayer player=new();
 readonly string store=Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.LocalApplicationData),"SonicForge","radio-stations.json");
 readonly string recordingRoot=Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.MyMusic),"SonicForge","Radioaufnahmen");
 CancellationTokenSource? recordingCts; FileStream? recordingFile; string currentStreamUrl=""; string currentStationName=""; string currentTitle=""; string currentRecordingPath=""; DateTime recordingStarted; readonly DispatcherTimer recordingTimer=new(){Interval=TimeSpan.FromSeconds(1)};
 public RadioPodcastWindow(){InitializeComponent();StationList.ItemsSource=stations;EpisodeGrid.ItemsSource=episodes;SearchResultsGrid.ItemsSource=searchResults;RecordingPathText.Text="Speicherort: "+recordingRoot;LoadStations();player.MediaFailed+=(_,e)=>Dispatcher.Invoke(()=>StatusText.Text="Wiedergabe fehlgeschlagen: "+e.ErrorException.Message);recordingTimer.Tick+=(_,_)=>{if(recordingCts is not null)RecordingText.Text=$"● Aufnahme läuft  {(DateTime.Now-recordingStarted):hh\\:mm\\:ss}  {currentTitle}";};}
 void LoadStations(){try{if(File.Exists(store))foreach(var x in JsonSerializer.Deserialize<List<RadioStation>>(File.ReadAllText(store))??[])stations.Add(x);}catch{} }
 void Save(){Directory.CreateDirectory(Path.GetDirectoryName(store)!);File.WriteAllText(store,JsonSerializer.Serialize(stations));}
 async void SearchGermany_Click(object s,RoutedEventArgs eventArgs){searchResults.Clear();var q=SearchBox.Text.Trim();StatusText.Text="Deutsche Radiosender werden gesucht ...";var servers=new[]{"https://de1.api.radio-browser.info","https://nl1.api.radio-browser.info","https://at1.api.radio-browser.info"};Exception? last=null;foreach(var server in servers){try{using var h=new HttpClient{Timeout=TimeSpan.FromSeconds(12)};h.DefaultRequestHeaders.UserAgent.ParseAdd("SonicForge-MP3-Studio/0.1");var url=server+"/json/stations/search?countrycode=DE&hidebroken=true&order=clickcount&reverse=true&limit=200"+(q.Length>0?"&name="+Uri.EscapeDataString(q):"");var json=await h.GetStringAsync(url);using var d=JsonDocument.Parse(json);foreach(var e in d.RootElement.EnumerateArray()){var name=Value(e,"name");var stream=Value(e,"url_resolved");if(name.Length==0||stream.Length==0)continue;searchResults.Add(new(name,stream,Value(e,"state"),Value(e,"tags"),Value(e,"codec")));}StatusText.Text=$"{searchResults.Count} deutsche Radiosender gefunden.";return;}catch(Exception ex){last=ex;}}StatusText.Text="Sendersuche fehlgeschlagen: "+last?.Message;}
 static string Value(JsonElement e,string n)=>e.TryGetProperty(n,out var v)?v.GetString()?.Trim()??"":"";
 void SearchResults_DoubleClick(object s,MouseButtonEventArgs e){if(SearchResultsGrid.SelectedItem is GermanStation x){StationNameBox.Text=x.Name;StationUrlBox.Text=x.Url;Play(x.Name,x.Url);StatusText.Text="Sender gestartet. Aufnahme kann jetzt gestartet werden.";}}
 void AddStation_Click(object s,RoutedEventArgs e){if(!Uri.TryCreate(StationUrlBox.Text.Trim(),UriKind.Absolute,out _)){StatusText.Text="Bitte eine gültige Stream-URL eingeben.";return;}stations.Add(new(StationNameBox.Text.Trim().Length>0?StationNameBox.Text.Trim():"Eigener Radiosender",StationUrlBox.Text.Trim()));Save();StatusText.Text="Radiosender gespeichert.";}
 void Play(string name,string url){try{currentStationName=name;currentStreamUrl=url;StationNameBox.Text=name;StationUrlBox.Text=url;player.Close();player.Open(new Uri(url));player.Play();NowPlayingText.Text=name;StatusText.Text="Wiedergabe gestartet.";}catch(Exception ex){StatusText.Text="Wiedergabe nicht möglich: "+ex.Message;}}
 void StationList_DoubleClick(object s,MouseButtonEventArgs e){if(StationList.SelectedItem is RadioStation x)Play(x.Name,x.Url);}
 async void Record_Click(object s,RoutedEventArgs e){if(recordingCts is not null)return;var url=StationUrlBox.Text.Trim();var name=StationNameBox.Text.Trim();if(!Uri.TryCreate(url,UriKind.Absolute,out _)){StatusText.Text="Zuerst einen Sender doppelt anklicken.";return;}currentStreamUrl=url;currentStationName=name.Length>0?name:"Radiosender";recordingCts=new();recordingStarted=DateTime.Now;RecordButton.IsEnabled=false;StopRecordButton.IsEnabled=true;recordingTimer.Start();try{await RecordStreamAsync(url,currentStationName,recordingCts.Token);}catch(OperationCanceledException){StatusText.Text="Radioaufnahme beendet.";}catch(Exception ex){StatusText.Text="Aufnahme fehlgeschlagen: "+ex.Message;}finally{await CloseRecordingAsync();recordingTimer.Stop();recordingCts?.Dispose();recordingCts=null;RecordButton.IsEnabled=true;StopRecordButton.IsEnabled=false;RecordingText.Text="Aufnahme bereit";}}
 void StopRecord_Click(object s,RoutedEventArgs e){StopRecordButton.IsEnabled=false;recordingCts?.Cancel();}
 async Task RecordStreamAsync(string url,string station,CancellationToken token){Directory.CreateDirectory(recordingRoot);using var handler=new HttpClientHandler{AllowAutoRedirect=true};using var h=new HttpClient(handler){Timeout=Timeout.InfiniteTimeSpan};using var req=new HttpRequestMessage(HttpMethod.Get,url);req.Headers.TryAddWithoutValidation("Icy-MetaData","1");req.Headers.UserAgent.ParseAdd("SonicForge-MP3-Studio/0.2");using var response=await h.SendAsync(req,HttpCompletionOption.ResponseHeadersRead,token);response.EnsureSuccessStatusCode();var media=response.Content.Headers.ContentType?.MediaType?.ToLowerInvariant()??"";if(!media.Contains("mpeg")&&!media.Contains("mp3")){throw new InvalidOperationException($"Diese erste Aufnahmephase unterstützt direkte MP3-Streams. Senderformat: {media}");}var metaInt=GetIcyMetaInt(response);await using var input=await response.Content.ReadAsStreamAsync(token);currentTitle="";await OpenRecordingAsync(station,"",token);if(metaInt<=0){StatusText.Text="Aufnahme läuft ohne Titelmetadaten.";await CopyUntilEndAsync(input,token);return;}var audio=new byte[metaInt];while(true){var got=await ReadExactOrEndAsync(input,audio,token);if(got==0)break;await recordingFile!.WriteAsync(audio.AsMemory(0,got),token);if(got<metaInt)break;var len=input.ReadByte();if(len<0)break;var metaBytes=new byte[len*16];if(metaBytes.Length>0)await ReadExactAsync(input,metaBytes,token);var metadata=Encoding.Latin1.GetString(metaBytes).TrimEnd('\0');var title=ExtractStreamTitle(metadata);if(title.Length>0&&!title.Equals(currentTitle,StringComparison.Ordinal)){await RotateForTitleAsync(station,title,token);}}}
 static int GetIcyMetaInt(HttpResponseMessage r){if(r.Headers.TryGetValues("icy-metaint",out var v)&&int.TryParse(v.FirstOrDefault(),out var n))return n;if(r.Content.Headers.TryGetValues("icy-metaint",out v)&&int.TryParse(v.FirstOrDefault(),out n))return n;return 0;}
 async Task RotateForTitleAsync(string station,string title,CancellationToken token){await CloseRecordingAsync();currentTitle=title;await OpenRecordingAsync(station,title,token);Dispatcher.Invoke(()=>{NowPlayingText.Text=title;StatusText.Text="Titel erkannt und neue MP3 begonnen.";});}
 async Task OpenRecordingAsync(string station,string title,CancellationToken token){var folder=Path.Combine(recordingRoot,SafeName(station));Directory.CreateDirectory(folder);var stem=title.Length>0?SafeName(title):$"{SafeName(station)} - Aufnahme {DateTime.Now:yyyy-MM-dd HH-mm-ss}";currentRecordingPath=UniquePath(Path.Combine(folder,stem+".mp3"));recordingFile=new FileStream(currentRecordingPath,FileMode.CreateNew,FileAccess.Write,FileShare.Read,81920,true);await Task.CompletedTask;Dispatcher.Invoke(()=>RecordingPathText.Text="Datei: "+currentRecordingPath);}
 async Task CloseRecordingAsync(){if(recordingFile is null)return;var path=currentRecordingPath;await recordingFile.FlushAsync();await recordingFile.DisposeAsync();recordingFile=null;if(new FileInfo(path).Length<4096){File.Delete(path);return;}WriteTags(path,currentTitle,currentStationName);}
 static void WriteTags(string path,string streamTitle,string station){try{using var f=TagLib.File.Create(path);var artist="";var title=streamTitle;var split=streamTitle.IndexOf(" - ",StringComparison.Ordinal);if(split>0){artist=streamTitle[..split].Trim();title=streamTitle[(split+3)..].Trim();}f.Tag.Title=title.Length>0?title:Path.GetFileNameWithoutExtension(path);if(artist.Length>0)f.Tag.Performers=[artist];f.Tag.Album=station;f.Tag.Comment="Aufgenommen mit SonicForge Internetradio";f.Save();}catch{} }
 static string ExtractStreamTitle(string m){var x=Regex.Match(m,"StreamTitle='(.*?)';",RegexOptions.IgnoreCase);return x.Success?x.Groups[1].Value.Trim():"";}
 static string SafeName(string s){foreach(var c in Path.GetInvalidFileNameChars())s=s.Replace(c,'_');s=Regex.Replace(s,@"\s+"," ").Trim().Trim('.');return s.Length==0?"Unbenannt":s.Length>150?s[..150]:s;}
 static string UniquePath(string p){if(!File.Exists(p))return p;var d=Path.GetDirectoryName(p)!;var n=Path.GetFileNameWithoutExtension(p);for(var i=2;;i++){var q=Path.Combine(d,$"{n} ({i}).mp3");if(!File.Exists(q))return q;}}
 static async Task<int> ReadExactOrEndAsync(Stream s,byte[] b,CancellationToken t){var o=0;while(o<b.Length){var n=await s.ReadAsync(b.AsMemory(o),t);if(n==0)break;o+=n;}return o;}
 static async Task ReadExactAsync(Stream s,byte[] b,CancellationToken t){var o=0;while(o<b.Length){var n=await s.ReadAsync(b.AsMemory(o),t);if(n==0)throw new EndOfStreamException();o+=n;}}
 async Task CopyUntilEndAsync(Stream s,CancellationToken t){var b=new byte[81920];while(true){var n=await s.ReadAsync(b,t);if(n==0)break;await recordingFile!.WriteAsync(b.AsMemory(0,n),t);}}
 async void LoadFeed_Click(object s,RoutedEventArgs e){episodes.Clear();if(!Uri.TryCreate(FeedUrlBox.Text.Trim(),UriKind.Absolute,out var u)){StatusText.Text="Bitte eine gültige RSS-Adresse eingeben.";return;}try{StatusText.Text="Podcast wird geladen ...";using var h=new HttpClient();h.DefaultRequestHeaders.UserAgent.ParseAdd("SonicForge/1.0");var xml=await h.GetStringAsync(u);var d=XDocument.Parse(xml);foreach(var i in d.Descendants("item").Take(200)){var title=(string?)i.Element("title")??"Unbenannte Folge";var enc=i.Elements().FirstOrDefault(x=>x.Name.LocalName=="enclosure");var url=(string?)enc?.Attribute("url")??"";if(url.Length>0)episodes.Add(new(title,url,(string?)i.Element("pubDate")??""));}StatusText.Text=$"{episodes.Count} Podcast-Folgen geladen.";}catch(Exception ex){StatusText.Text="RSS konnte nicht geladen werden: "+ex.Message;}}
 void EpisodeGrid_DoubleClick(object s,MouseButtonEventArgs e){if(EpisodeGrid.SelectedItem is PodcastEpisode x)Play(x.Title,x.Url);}
 void Pause_Click(object s,RoutedEventArgs e){player.Pause();StatusText.Text="Wiedergabe pausiert.";}void Resume_Click(object s,RoutedEventArgs e){player.Play();StatusText.Text="Wiedergabe fortgesetzt.";}void Stop_Click(object s,RoutedEventArgs e){player.Stop();NowPlayingText.Text="Bereit";StatusText.Text="Wiedergabe gestoppt.";}
 void Remove_Click(object s,RoutedEventArgs e){if(StationList.SelectedItem is RadioStation x){stations.Remove(x);Save();StatusText.Text="Radiosender entfernt.";}}
 protected override void OnClosed(EventArgs e){recordingCts?.Cancel();player.Close();base.OnClosed(e);}
}